/**
 * PostgreSQL schema (authoritative state).
 *
 * Conventions:
 *  - UUID primary keys generated by the application (v7, time ordered), UTC timestamptz columns.
 *  - Amounts are integer base units in NUMERIC(78,0); prices are NUMERIC(60,30). No floats for money.
 *  - PAPER and LIVE rows are kept apart with composite (portfolio_id, mode) foreign keys, so a
 *    PAPER order can never reference a LIVE portfolio and vice versa.
 *  - Append-only tables (ledger_entries, audit_events, order_state_transitions) are protected by
 *    triggers in the hand-written migration 0001.
 */
import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  check,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

const ts = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });
const createdAt = () => ts("created_at").notNull().defaultNow();
const updatedAt = () => ts("updated_at").notNull().defaultNow();
/** Integer base units (token base units, USDC micro-units, lamports). */
const raw = (name: string) => numeric(name, { precision: 78, scale: 0 });
/** Exact decimal price or ratio. */
const dec = (name: string) => numeric(name, { precision: 60, scale: 30 });
const pk = () => uuid("id").primaryKey().defaultRandom();
const modeCol = () => text("mode").notNull();
const modeCheck = (table: string, col: unknown) =>
  check(`${table}_mode_chk`, sql`${col} in ('PAPER', 'LIVE')`);

// ---------------------------------------------------------------------------------------------
// Portfolios, wallets, balances
// ---------------------------------------------------------------------------------------------

export const portfolios = pgTable(
  "portfolios",
  {
    id: pk(),
    name: text("name").notNull(),
    mode: modeCol(),
    status: text("status").notNull().default("ACTIVE"),
    baseMint: text("base_mint").notNull(),
    entriesPaused: boolean("entries_paused").notNull().default(false),
    submissionsPaused: boolean("submissions_paused").notNull().default(false),
    liveDisabled: boolean("live_disabled").notNull().default(true),
    liquidationRequestedAt: ts("liquidation_requested_at"),
    pauseReason: text("pause_reason"),
    version: integer("version").notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("portfolios_id_mode_uq").on(t.id, t.mode),
    unique("portfolios_name_uq").on(t.name),
    modeCheck("portfolios", t.mode),
    check("portfolios_status_chk", sql`${t.status} in ('ACTIVE', 'ARCHIVED')`),
  ],
);

/** Public wallet metadata only. There is deliberately no column for key material. */
export const wallets = pgTable(
  "wallets",
  {
    id: pk(),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    publicKey: text("public_key").notNull(),
    label: text("label"),
    createdAt: createdAt(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    unique("wallets_public_key_mode_uq").on(t.publicKey, t.mode),
    modeCheck("wallets", t.mode),
  ],
);

/**
 * Cached balances per portfolio, locked with SELECT ... FOR UPDATE during reservations.
 * The ledger is authoritative; this row is rebuilt from it after restarts and verified continuously.
 */
export const portfolioBalances = pgTable(
  "portfolio_balances",
  {
    portfolioId: uuid("portfolio_id").primaryKey(),
    mode: modeCol(),
    cashRaw: raw("cash_raw").notNull().default("0"),
    reservedRaw: raw("reserved_raw").notNull().default("0"),
    solLamports: raw("sol_lamports").notNull().default("0"),
    solReservedLamports: raw("sol_reserved_lamports").notNull().default("0"),
    version: integer("version").notNull().default(0),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    modeCheck("portfolio_balances", t.mode),
    check("portfolio_balances_nonneg_chk", sql`${t.reservedRaw} >= 0 and ${t.solReservedLamports} >= 0`),
  ],
);

// ---------------------------------------------------------------------------------------------
// Market reference data and observations
// ---------------------------------------------------------------------------------------------

export const tokens = pgTable(
  "tokens",
  {
    id: pk(),
    network: text("network").notNull(),
    mint: text("mint").notNull(),
    /** Untrusted display metadata from providers; never used for identity. */
    symbol: text("symbol"),
    name: text("name"),
    decimals: integer("decimals"),
    tokenProgram: text("token_program"),
    allowlisted: boolean("allowlisted").notNull().default(false),
    allowlistNote: text("allowlist_note"),
    preferredPoolAddress: text("preferred_pool_address"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [unique("tokens_network_mint_uq").on(t.network, t.mint)],
);

export const pools = pgTable(
  "pools",
  {
    id: pk(),
    network: text("network").notNull(),
    poolAddress: text("pool_address").notNull(),
    tokenId: uuid("token_id")
      .notNull()
      .references(() => tokens.id),
    baseMint: text("base_mint").notNull(),
    quoteMint: text("quote_mint").notNull(),
    dex: text("dex"),
    poolCreatedAt: ts("pool_created_at"),
    provider: text("provider").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [unique("pools_network_address_uq").on(t.network, t.poolAddress)],
);

/** Exact raw provider payloads, deduplicated by hash, referenced from observations and candles. */
export const rawPayloads = pgTable(
  "raw_payloads",
  {
    id: pk(),
    provider: text("provider").notNull(),
    sha256: text("sha256").notNull(),
    payload: jsonb("payload").notNull(),
    byteSize: integer("byte_size").notNull(),
    receivedAt: ts("received_at").notNull(),
  },
  (t) => [unique("raw_payloads_sha256_uq").on(t.sha256)],
);

export const marketObservations = pgTable(
  "market_observations",
  {
    id: pk(),
    network: text("network").notNull(),
    mint: text("mint").notNull(),
    poolAddress: text("pool_address"),
    provider: text("provider").notNull(),
    kind: text("kind").notNull(),
    eventAt: ts("event_at").notNull(),
    receivedAt: ts("received_at").notNull(),
    sourceSlot: bigint("source_slot", { mode: "bigint" }),
    parserVersion: text("parser_version").notNull(),
    rawPayloadId: uuid("raw_payload_id").references(() => rawPayloads.id),
    data: jsonb("data").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index("market_observations_mint_kind_received_idx").on(t.mint, t.kind, t.receivedAt),
    check(
      "market_observations_kind_chk",
      sql`${t.kind} in ('POOL_SNAPSHOT', 'MINT_ACCOUNT', 'LARGEST_ACCOUNTS', 'HOLDER_OWNERS', 'QUOTE', 'CANDLE_REVISION')`,
    ),
  ],
);

/**
 * Closed one-minute candles. Rows are only written once a candle has closed and its grace
 * window has passed (see the late-data policy in docs/data-policy.md). `observedAt` is when we
 * first stored it; strategies only use candles with observedAt <= decision time.
 */
export const candles = pgTable(
  "candles",
  {
    id: pk(),
    network: text("network").notNull(),
    poolAddress: text("pool_address").notNull(),
    mint: text("mint").notNull(),
    provider: text("provider").notNull(),
    interval: text("interval").notNull(),
    openTime: ts("open_time").notNull(),
    closeTime: ts("close_time").notNull(),
    open: dec("open").notNull(),
    high: dec("high").notNull(),
    low: dec("low").notNull(),
    close: dec("close").notNull(),
    /** Null when the provider does not supply real volume. Never zero-filled. */
    volumeUsd: dec("volume_usd"),
    priceCurrency: text("price_currency").notNull(),
    observedAt: ts("observed_at").notNull(),
    parserVersion: text("parser_version").notNull(),
    rawPayloadId: uuid("raw_payload_id").references(() => rawPayloads.id),
    revisionCount: integer("revision_count").notNull().default(0),
    datasetTag: text("dataset_tag").notNull().default("real"),
  },
  (t) => [
    unique("candles_series_open_uq").on(t.network, t.poolAddress, t.provider, t.interval, t.openTime),
    index("candles_mint_open_idx").on(t.mint, t.openTime),
    check("candles_interval_chk", sql`${t.interval} in ('1m')`),
    check("candles_dataset_tag_chk", sql`${t.datasetTag} in ('real', 'synthetic')`),
    check("candles_ohlc_chk", sql`${t.high} >= ${t.low} and ${t.low} >= 0`),
  ],
);

// ---------------------------------------------------------------------------------------------
// Screening, strategy, risk
// ---------------------------------------------------------------------------------------------

export const screeningAssessments = pgTable(
  "screening_assessments",
  {
    id: pk(),
    tokenId: uuid("token_id")
      .notNull()
      .references(() => tokens.id),
    network: text("network").notNull(),
    mint: text("mint").notNull(),
    verdict: text("verdict").notNull(),
    checks: jsonb("checks").notNull(),
    intendedSizeRaw: raw("intended_size_raw").notNull(),
    screenerVersion: text("screener_version").notNull(),
    inputs: jsonb("inputs").notNull(),
    assessedAt: ts("assessed_at").notNull(),
    expiresAt: ts("expires_at").notNull(),
  },
  (t) => [
    index("screening_mint_assessed_idx").on(t.mint, t.assessedAt),
    check("screening_verdict_chk", sql`${t.verdict} in ('PASS', 'REJECT', 'UNKNOWN')`),
  ],
);

export const strategyVersions = pgTable(
  "strategy_versions",
  {
    id: pk(),
    name: text("name").notNull(),
    version: text("version").notNull(),
    params: jsonb("params").notNull(),
    paramsHash: text("params_hash").notNull(),
    description: text("description"),
    createdAt: createdAt(),
  },
  (t) => [unique("strategy_versions_name_hash_uq").on(t.name, t.version, t.paramsHash)],
);

export const riskPolicies = pgTable(
  "risk_policies",
  {
    id: pk(),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    version: integer("version").notNull(),
    label: text("label").notNull(),
    params: jsonb("params").notNull(),
    active: boolean("active").notNull().default(false),
    createdBy: text("created_by").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    unique("risk_policies_portfolio_version_uq").on(t.portfolioId, t.version),
    uniqueIndex("risk_policies_one_active_uq")
      .on(t.portfolioId)
      .where(sql`${t.active}`),
    modeCheck("risk_policies", t.mode),
  ],
);

export const signals = pgTable(
  "signals",
  {
    id: pk(),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    strategyVersionId: uuid("strategy_version_id")
      .notNull()
      .references(() => strategyVersions.id),
    tokenId: uuid("token_id")
      .notNull()
      .references(() => tokens.id),
    mint: text("mint").notNull(),
    side: text("side").notNull(),
    signalAt: ts("signal_at").notNull(),
    expiresAt: ts("expires_at").notNull(),
    evidence: jsonb("evidence").notNull(),
    reason: text("reason").notNull(),
    status: text("status").notNull().default("NEW"),
    statusReason: text("status_reason"),
    idempotencyKey: text("idempotency_key").notNull(),
    datasetVersion: text("dataset_version"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    unique("signals_id_portfolio_mode_uq").on(t.id, t.portfolioId, t.mode),
    unique("signals_idempotency_uq").on(t.idempotencyKey),
    index("signals_portfolio_created_idx").on(t.portfolioId, t.createdAt),
    modeCheck("signals", t.mode),
    check("signals_side_chk", sql`${t.side} in ('BUY', 'SELL')`),
    check("signals_status_chk", sql`${t.status} in ('NEW', 'ACCEPTED', 'REJECTED', 'EXPIRED', 'EXECUTED')`),
  ],
);

// ---------------------------------------------------------------------------------------------
// Orders and execution
// ---------------------------------------------------------------------------------------------

export const orders = pgTable(
  "orders",
  {
    id: pk(),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    signalId: uuid("signal_id"),
    strategyVersionId: uuid("strategy_version_id").references(() => strategyVersions.id),
    tokenId: uuid("token_id")
      .notNull()
      .references(() => tokens.id),
    mint: text("mint").notNull(),
    side: text("side").notNull(),
    state: text("state").notNull(),
    version: integer("version").notNull().default(0),
    idempotencyKey: text("idempotency_key").notNull(),
    /** BUY: USDC base units to spend. */
    notionalRaw: raw("notional_raw"),
    /** SELL: token base units to sell. */
    quantityRaw: raw("quantity_raw"),
    reservedQuoteRaw: raw("reserved_quote_raw").notNull().default("0"),
    reservedFeeLamports: raw("reserved_fee_lamports").notNull().default("0"),
    maxSlippageBps: integer("max_slippage_bps").notNull(),
    maxPriceImpactBps: integer("max_price_impact_bps").notNull(),
    maxNetworkFeeLamports: raw("max_network_fee_lamports").notNull(),
    reason: text("reason").notNull(),
    purpose: text("purpose").notNull(),
    expiresAt: ts("expires_at").notNull(),
    lastError: text("last_error"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    foreignKey({
      name: "orders_signal_same_portfolio_fk",
      columns: [t.signalId, t.portfolioId, t.mode],
      foreignColumns: [signals.id, signals.portfolioId, signals.mode],
    }),
    unique("orders_id_portfolio_mode_uq").on(t.id, t.portfolioId, t.mode),
    unique("orders_idempotency_uq").on(t.idempotencyKey),
    index("orders_portfolio_state_idx").on(t.portfolioId, t.state),
    modeCheck("orders", t.mode),
    check("orders_side_chk", sql`${t.side} in ('BUY', 'SELL')`),
    check("orders_purpose_chk", sql`${t.purpose} in ('ENTRY', 'EXIT', 'LIQUIDATION')`),
    check(
      "orders_state_chk",
      sql`${t.state} in ('PROPOSED','REJECTED','RESERVED','PREPARED','SUBMITTED','UNKNOWN','CONFIRMED','FINALIZED','RECONCILED','FAILED','CANCELLED','MANUAL_REVIEW')`,
    ),
    check(
      "orders_amount_chk",
      sql`(${t.side} = 'BUY' and ${t.notionalRaw} > 0) or (${t.side} = 'SELL' and ${t.quantityRaw} > 0)`,
    ),
  ],
);

export const orderStateTransitions = pgTable(
  "order_state_transitions",
  {
    id: pk(),
    orderId: uuid("order_id")
      .notNull()
      .references(() => orders.id),
    fromState: text("from_state"),
    toState: text("to_state").notNull(),
    fromVersion: integer("from_version"),
    toVersion: integer("to_version").notNull(),
    reason: text("reason").notNull(),
    actor: text("actor").notNull(),
    at: ts("at").notNull(),
  },
  (t) => [index("order_transitions_order_idx").on(t.orderId, t.toVersion)],
);

export const riskDecisions = pgTable(
  "risk_decisions",
  {
    id: pk(),
    signalId: uuid("signal_id"),
    orderId: uuid("order_id"),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    policyId: uuid("policy_id").references(() => riskPolicies.id),
    decision: text("decision").notNull(),
    checks: jsonb("checks").notNull(),
    decidedAt: ts("decided_at").notNull(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    foreignKey({
      name: "risk_decisions_signal_same_portfolio_fk",
      columns: [t.signalId, t.portfolioId, t.mode],
      foreignColumns: [signals.id, signals.portfolioId, signals.mode],
    }),
    foreignKey({
      name: "risk_decisions_order_same_portfolio_fk",
      columns: [t.orderId, t.portfolioId, t.mode],
      foreignColumns: [orders.id, orders.portfolioId, orders.mode],
    }),
    index("risk_decisions_portfolio_decided_idx").on(t.portfolioId, t.decidedAt),
    modeCheck("risk_decisions", t.mode),
    check("risk_decisions_decision_chk", sql`${t.decision} in ('APPROVED', 'REJECTED')`),
  ],
);

export const reservations = pgTable(
  "reservations",
  {
    id: pk(),
    orderId: uuid("order_id").notNull(),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    quoteRaw: raw("quote_raw").notNull(),
    feeLamports: raw("fee_lamports").notNull(),
    status: text("status").notNull().default("ACTIVE"),
    createdAt: createdAt(),
    releasedAt: ts("released_at"),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    foreignKey({
      name: "reservations_order_same_portfolio_fk",
      columns: [t.orderId, t.portfolioId, t.mode],
      foreignColumns: [orders.id, orders.portfolioId, orders.mode],
    }),
    unique("reservations_order_uq").on(t.orderId),
    modeCheck("reservations", t.mode),
    check("reservations_status_chk", sql`${t.status} in ('ACTIVE', 'RELEASED', 'CONSUMED')`),
  ],
);

export const orderAttempts = pgTable(
  "order_attempts",
  {
    id: pk(),
    orderId: uuid("order_id")
      .notNull()
      .references(() => orders.id),
    attemptNo: integer("attempt_no").notNull(),
    provider: text("provider").notNull(),
    providerRequestId: text("provider_request_id"),
    /** Hash of the prepared transaction message (paper: hash of the simulated intent). */
    txDigest: text("tx_digest"),
    expectedSignature: text("expected_signature"),
    status: text("status").notNull(),
    quote: jsonb("quote"),
    lastValidBlockHeight: text("last_valid_block_height"),
    quoteReceivedAt: ts("quote_received_at"),
    preparedAt: ts("prepared_at"),
    submittedAt: ts("submitted_at"),
    resolvedAt: ts("resolved_at"),
    errorCode: text("error_code"),
    errorMessage: text("error_message"),
    simulation: jsonb("simulation"),
  },
  (t) => [
    unique("order_attempts_order_no_uq").on(t.orderId, t.attemptNo),
    check(
      "order_attempts_status_chk",
      sql`${t.status} in ('PREPARED','SUBMITTING','SUBMITTED','UNKNOWN','CONFIRMED','FINALIZED','FAILED','EXPIRED','CANCELLED')`,
    ),
  ],
);

export const fills = pgTable(
  "fills",
  {
    id: pk(),
    orderId: uuid("order_id").notNull(),
    attemptId: uuid("attempt_id")
      .notNull()
      .references(() => orderAttempts.id),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    mint: text("mint").notNull(),
    side: text("side").notNull(),
    tokenQtyRaw: raw("token_qty_raw").notNull(),
    quoteAmountRaw: raw("quote_amount_raw").notNull(),
    platformFeeRaw: raw("platform_fee_raw").notNull().default("0"),
    platformFeeMint: text("platform_fee_mint"),
    networkFeeLamports: raw("network_fee_lamports").notNull().default("0"),
    networkFeeQuoteEstimateRaw: raw("network_fee_quote_estimate_raw").notNull().default("0"),
    price: dec("price").notNull(),
    realizedPnlRaw: raw("realized_pnl_raw"),
    costBasisRemovedRaw: raw("cost_basis_removed_raw"),
    isSimulated: boolean("is_simulated").notNull(),
    fillModelVersion: text("fill_model_version"),
    approximate: boolean("approximate").notNull().default(false),
    notes: text("notes"),
    filledAt: ts("filled_at").notNull(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    foreignKey({
      name: "fills_order_same_portfolio_fk",
      columns: [t.orderId, t.portfolioId, t.mode],
      foreignColumns: [orders.id, orders.portfolioId, orders.mode],
    }),
    unique("fills_id_portfolio_mode_uq").on(t.id, t.portfolioId, t.mode),
    unique("fills_attempt_uq").on(t.attemptId),
    index("fills_portfolio_filled_idx").on(t.portfolioId, t.filledAt),
    modeCheck("fills", t.mode),
    check("fills_sim_mode_chk", sql`(${t.mode} = 'PAPER') = ${t.isSimulated}`),
  ],
);

export const positions = pgTable(
  "positions",
  {
    id: pk(),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    tokenId: uuid("token_id")
      .notNull()
      .references(() => tokens.id),
    mint: text("mint").notNull(),
    status: text("status").notNull(),
    quantityRaw: raw("quantity_raw").notNull(),
    costBasisRaw: raw("cost_basis_raw").notNull(),
    realizedPnlRaw: raw("realized_pnl_raw").notNull().default("0"),
    entryOrderId: uuid("entry_order_id"),
    strategyVersionId: uuid("strategy_version_id").references(() => strategyVersions.id),
    entryReason: text("entry_reason"),
    exitReason: text("exit_reason"),
    /** Conservative value: exit quote at actual size, or 0 when no exit route exists. */
    markValueRaw: raw("mark_value_raw"),
    markSource: text("mark_source"),
    markAt: ts("mark_at"),
    peakMarkValueRaw: raw("peak_mark_value_raw"),
    strandedSince: ts("stranded_since"),
    openedAt: ts("opened_at").notNull(),
    closedAt: ts("closed_at"),
    version: integer("version").notNull().default(0),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    foreignKey({
      name: "positions_entry_order_same_portfolio_fk",
      columns: [t.entryOrderId, t.portfolioId, t.mode],
      foreignColumns: [orders.id, orders.portfolioId, orders.mode],
    }),
    uniqueIndex("positions_one_active_per_token_uq")
      .on(t.portfolioId, t.mint)
      .where(sql`${t.status} in ('OPEN', 'CLOSING', 'STRANDED')`),
    modeCheck("positions", t.mode),
    check("positions_status_chk", sql`${t.status} in ('OPEN', 'CLOSING', 'STRANDED', 'CLOSED')`),
    check("positions_qty_chk", sql`${t.quantityRaw} >= 0 and ${t.costBasisRaw} >= 0`),
  ],
);

/** Append-only double-entry ledger. Each journal balances per asset (deferred trigger in 0001). */
export const ledgerEntries = pgTable(
  "ledger_entries",
  {
    id: pk(),
    journalId: uuid("journal_id").notNull(),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    account: text("account").notNull(),
    asset: text("asset").notNull(),
    /** Signed base units: positive = debit, negative = credit. */
    amountRaw: raw("amount_raw").notNull(),
    entryType: text("entry_type").notNull(),
    orderId: uuid("order_id"),
    fillId: uuid("fill_id"),
    memo: text("memo"),
    createdAt: createdAt(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    foreignKey({
      name: "ledger_order_same_portfolio_fk",
      columns: [t.orderId, t.portfolioId, t.mode],
      foreignColumns: [orders.id, orders.portfolioId, orders.mode],
    }),
    foreignKey({
      name: "ledger_fill_same_portfolio_fk",
      columns: [t.fillId, t.portfolioId, t.mode],
      foreignColumns: [fills.id, fills.portfolioId, fills.mode],
    }),
    index("ledger_portfolio_account_idx").on(t.portfolioId, t.account, t.asset),
    index("ledger_journal_idx").on(t.journalId),
    modeCheck("ledger_entries", t.mode),
    check("ledger_amount_nonzero_chk", sql`${t.amountRaw} <> 0`),
    check(
      "ledger_entry_type_chk",
      sql`${t.entryType} in ('DEPOSIT','WITHDRAWAL','ACQUISITION','DISPOSAL','FEE_NETWORK','FEE_PLATFORM','TRANSFER','ADJUSTMENT')`,
    ),
  ],
);

export const portfolioSnapshots = pgTable(
  "portfolio_snapshots",
  {
    id: pk(),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    at: ts("at").notNull(),
    cashRaw: raw("cash_raw").notNull(),
    reservedRaw: raw("reserved_raw").notNull(),
    positionsMarkRaw: raw("positions_mark_raw").notNull(),
    equityRaw: raw("equity_raw").notNull(),
    depositsRaw: raw("deposits_raw").notNull(),
    realizedPnlRaw: raw("realized_pnl_raw").notNull(),
    unrealizedPnlRaw: raw("unrealized_pnl_raw").notNull(),
    platformFeesRaw: raw("platform_fees_raw").notNull(),
    networkFeesLamports: raw("network_fees_lamports").notNull(),
    networkFeesQuoteEstimateRaw: raw("network_fees_quote_estimate_raw").notNull(),
    infraCostsRaw: raw("infra_costs_raw").notNull().default("0"),
    exposureRaw: raw("exposure_raw").notNull(),
    peakEquityRaw: raw("peak_equity_raw").notNull(),
    drawdownBps: integer("drawdown_bps").notNull(),
    openPositions: integer("open_positions").notNull(),
    strandedPositions: integer("stranded_positions").notNull(),
    markQuality: text("mark_quality").notNull(),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    index("portfolio_snapshots_portfolio_at_idx").on(t.portfolioId, t.at),
    modeCheck("portfolio_snapshots", t.mode),
  ],
);

// ---------------------------------------------------------------------------------------------
// Durable work: jobs, outbox, operator commands
// ---------------------------------------------------------------------------------------------

export const jobs = pgTable(
  "jobs",
  {
    id: pk(),
    kind: text("kind").notNull(),
    payload: jsonb("payload").notNull(),
    status: text("status").notNull().default("QUEUED"),
    runAt: ts("run_at").notNull().defaultNow(),
    leaseOwner: text("lease_owner"),
    leaseUntil: ts("lease_until"),
    attempts: integer("attempts").notNull().default(0),
    maxAttempts: integer("max_attempts").notNull().default(10),
    lastError: text("last_error"),
    dedupeKey: text("dedupe_key"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("jobs_dedupe_active_uq")
      .on(t.dedupeKey)
      .where(sql`${t.dedupeKey} is not null and ${t.status} in ('QUEUED', 'LEASED')`),
    index("jobs_ready_idx").on(t.status, t.runAt),
    check("jobs_status_chk", sql`${t.status} in ('QUEUED', 'LEASED', 'DONE', 'DEAD')`),
  ],
);

export const outboxEvents = pgTable(
  "outbox_events",
  {
    id: pk(),
    aggregateType: text("aggregate_type").notNull(),
    aggregateId: text("aggregate_id").notNull(),
    eventType: text("event_type").notNull(),
    payload: jsonb("payload").notNull(),
    createdAt: createdAt(),
    publishedAt: ts("published_at"),
  },
  (t) => [index("outbox_unpublished_idx").on(t.publishedAt, t.createdAt)],
);

export const operatorCommands = pgTable(
  "operator_commands",
  {
    id: pk(),
    portfolioId: uuid("portfolio_id").notNull(),
    mode: modeCol(),
    command: text("command").notNull(),
    status: text("status").notNull().default("ACCEPTED"),
    idempotencyKey: text("idempotency_key").notNull(),
    requestedBy: text("requested_by").notNull(),
    reason: text("reason"),
    requestedAt: ts("requested_at").notNull(),
    appliedAt: ts("applied_at"),
    completedAt: ts("completed_at"),
    result: jsonb("result"),
  },
  (t) => [
    foreignKey({ columns: [t.portfolioId, t.mode], foreignColumns: [portfolios.id, portfolios.mode] }),
    unique("operator_commands_idempotency_uq").on(t.idempotencyKey),
    modeCheck("operator_commands", t.mode),
    check(
      "operator_commands_command_chk",
      sql`${t.command} in ('PAUSE_ENTRIES', 'PAUSE_ALL', 'LIQUIDATE', 'RESUME', 'DISABLE_LIVE')`,
    ),
    check(
      "operator_commands_status_chk",
      sql`${t.status} in ('ACCEPTED', 'APPLIED', 'COMPLETED', 'PARTIAL', 'FAILED')`,
    ),
  ],
);

// ---------------------------------------------------------------------------------------------
// Audit, incidents, health
// ---------------------------------------------------------------------------------------------

export const auditEvents = pgTable(
  "audit_events",
  {
    id: pk(),
    at: ts("at").notNull(),
    actor: text("actor").notNull(),
    action: text("action").notNull(),
    subjectType: text("subject_type"),
    subjectId: text("subject_id"),
    details: jsonb("details").notNull(),
    ip: text("ip"),
    requestId: text("request_id"),
  },
  (t) => [index("audit_events_at_idx").on(t.at)],
);

export const systemIncidents = pgTable(
  "system_incidents",
  {
    id: pk(),
    severity: text("severity").notNull(),
    kind: text("kind").notNull(),
    message: text("message").notNull(),
    details: jsonb("details").notNull(),
    portfolioId: uuid("portfolio_id"),
    openedAt: ts("opened_at").notNull(),
    resolvedAt: ts("resolved_at"),
    dedupeKey: text("dedupe_key"),
  },
  (t) => [
    uniqueIndex("system_incidents_open_dedupe_uq")
      .on(t.dedupeKey)
      .where(sql`${t.dedupeKey} is not null and ${t.resolvedAt} is null`),
    check("system_incidents_severity_chk", sql`${t.severity} in ('INFO', 'WARNING', 'CRITICAL')`),
  ],
);

export const providerHealth = pgTable("provider_health", {
  provider: text("provider").primaryKey(),
  status: text("status").notNull(),
  circuitState: text("circuit_state").notNull(),
  lastSuccessAt: ts("last_success_at"),
  lastFailureAt: ts("last_failure_at"),
  lastError: text("last_error"),
  consecutiveFailures: integer("consecutive_failures").notNull().default(0),
  requestsTotal: bigint("requests_total", { mode: "number" }).notNull().default(0),
  rateLimitedTotal: bigint("rate_limited_total", { mode: "number" }).notNull().default(0),
  updatedAt: updatedAt(),
});

export const serviceHeartbeats = pgTable(
  "service_heartbeats",
  {
    service: text("service").notNull(),
    instance: text("instance").notNull(),
    lastBeatAt: ts("last_beat_at").notNull(),
    startedAt: ts("started_at").notNull(),
    details: jsonb("details").notNull(),
  },
  (t) => [unique("service_heartbeats_uq").on(t.service, t.instance)],
);

// ---------------------------------------------------------------------------------------------
// Research: reports and parameter trials
// ---------------------------------------------------------------------------------------------

export const reports = pgTable(
  "reports",
  {
    id: pk(),
    kind: text("kind").notNull(),
    status: text("status").notNull(),
    title: text("title").notNull(),
    strategyVersionId: uuid("strategy_version_id").references(() => strategyVersions.id),
    portfolioId: uuid("portfolio_id"),
    datasetVersion: text("dataset_version"),
    datasetTag: text("dataset_tag").notNull(),
    request: jsonb("request").notNull(),
    results: jsonb("results"),
    error: text("error"),
    createdAt: createdAt(),
    completedAt: ts("completed_at"),
  },
  (t) => [
    check("reports_kind_chk", sql`${t.kind} in ('REPLAY', 'PAPER_RUN')`),
    check("reports_status_chk", sql`${t.status} in ('QUEUED', 'RUNNING', 'COMPLETED', 'FAILED')`),
    check("reports_dataset_tag_chk", sql`${t.datasetTag} in ('real', 'synthetic')`),
  ],
);

/** Every attempted parameter set is saved, profitable or not, to prevent selective reporting. */
export const parameterTrials = pgTable(
  "parameter_trials",
  {
    id: pk(),
    reportId: uuid("report_id")
      .notNull()
      .references(() => reports.id),
    strategyVersionId: uuid("strategy_version_id")
      .notNull()
      .references(() => strategyVersions.id),
    split: text("split").notNull(),
    metrics: jsonb("metrics").notNull(),
    createdAt: createdAt(),
  },
  (t) => [check("parameter_trials_split_chk", sql`${t.split} in ('train', 'validation', 'test')`)],
);

// ---------------------------------------------------------------------------------------------
// Auth sessions and API idempotency
// ---------------------------------------------------------------------------------------------

export const sessions = pgTable("sessions", {
  id: pk(),
  tokenHash: text("token_hash").notNull().unique(),
  csrfTokenHash: text("csrf_token_hash").notNull(),
  username: text("username").notNull(),
  createdAt: createdAt(),
  expiresAt: ts("expires_at").notNull(),
  revokedAt: ts("revoked_at"),
  ip: text("ip"),
  userAgent: text("user_agent"),
});

export const apiIdempotency = pgTable(
  "api_idempotency",
  {
    key: text("key").notNull(),
    route: text("route").notNull(),
    requestHash: text("request_hash").notNull(),
    statusCode: integer("status_code").notNull(),
    response: jsonb("response").notNull(),
    createdAt: createdAt(),
  },
  (t) => [unique("api_idempotency_key_route_uq").on(t.key, t.route)],
);
